(7531227, 1204293, 173844, '<td valign="top">Interesting cauldron effect.  A significance I get is that the sea never sleeps.  Pleasing yellow sunrise.</td>', 'Interesting cauldron effect.  A significance I get is that the sea never sleeps.  Pleasing yellow sunrise.', '2017-08-27 23:29:24.000000', NULL, 1),
(7531228, 1204353, 173844, '<td valign="top">Pretty and immediate.  I like the touch of red at the right.  A lot of noise.</td>', 'Pretty and immediate.  I like the touch of red at the right.  A lot of noise.', '2017-08-27 23:31:31.000000', NULL, 1),
(7531229, 1204278, 173844, '<td valign="top">I like the trees in silhouette.</td>', 'I like the trees in silhouette.', '2017-08-27 23:32:30.000000', NULL, 1),
(7531230, 1204351, 173844, '<td valign="top">Nice burst of sun.  I like the man''s sturdy, contemplative stance.</td>', 'Nice burst of sun.  I like the man''s sturdy, contemplative stance.', '2017-08-27 23:33:52.000000', NULL, 1),
(7531231, 1204227, 173844, '<td valign="top">Perfect title.  Invites one to feel philosophical.</td>', 'Perfect title.  Invites one to feel philosophical.', '2017-08-27 23:35:30.000000', NULL, 1),
(7531232, 1204342, 173844, '<td valign="top">Most honest image in the challenge.  The documentary tone is refreshing.</td>', 'Most honest image in the challenge.  The documentary tone is refreshing.', '2017-08-27 23:37:09.000000', NULL, 1),
(7531233, 1204331, 173844, '<td valign="top">An intimate portrait that pulls one sharply into the moment.  Handsome composition, pleasing bokeh.</td>', 'An intimate portrait that pulls one sharply into the moment.  Handsome composition, pleasing bokeh.', '2017-08-27 23:39:26.000000', NULL, 1),
(7531234, 1203960, 173844, '<td valign="top">I like this image.  Having seen almost the exact same one recently, though, I''m left feeling a bit jaded.</td>', 'I like this image.  Having seen almost the exact same one recently, though, I''m left feeling a bit jaded.', '2017-08-27 23:41:13.000000', NULL, 1),
(7531235, 1204337, 173844, '<td valign="top">A seemingly simple image that''s nicely composed and balanced, which strikes a chord with all dog owners.  The eagerness of the dog and the tautness of the leash provokes a big smile.  Curiously, the shadow resembles a cat.  I also like the colors, patterns and textures.  Nice.</td>', 'A seemingly simple image that''s nicely composed and balanced, which strikes a chord with all dog owners.  The eagerness of the dog and the tautness of the leash provokes a big smile.  Curiously, the shadow resembles a cat.  I also like the colors, patterns and textures.  Nice.', '2017-08-27 23:46:23.000000', NULL, 1),
(7531236, 1204161, 173844, '<td valign="top">Telling image of the workaday world.  Pleasing black and white.</td>', 'Telling image of the workaday world.  Pleasing black and white.', '2017-08-27 23:47:36.000000', NULL, 1),
(7531237, 1204330, 173844, '<td valign="top">Fine depiction of the shadow effect against a sun-drenched floor.  I also like how the shadow settles on the cat''s body.</td>', 'Fine depiction of the shadow effect against a sun-drenched floor.  I also like how the shadow settles on the cat''s body.', '2017-08-27 23:49:44.000000', NULL, 1),
(7531238, 1204301, 173844, '<td valign="top">Achieves an engaging level of abstraction while quite remaining true to its stark reality.  I''d put this on my wall.</td>', 'Achieves an engaging level of abstraction while quite remaining true to its stark reality.  I''d put this on my wall.', '2017-08-27 23:52:16.000000', NULL, 1),
(7531239, 1204245, 173844, '<td valign="top">Lovely sepia image, fine perspective and detail.  The large pots are sentinels that anchor her in repose.  Rewarding depth of field.</td>', 'Lovely sepia image, fine perspective and detail.  The large pots are sentinels that anchor her in repose.  Rewarding depth of field.', '2017-08-27 23:56:38.000000', NULL, 1),
(7531240, 1203778, 173844, '<td valign="top">Quaint house that looks fun to live in, shown in its pleasing environment.  Nice composition.</td>', 'Quaint house that looks fun to live in, shown in its pleasing environment.  Nice composition.', '2017-08-27 23:59:23.000000', NULL, 1),
(7531242, 1204245, 68504, '<td valign="top">it surely is.</td>', 'it surely is.', '2017-08-28 00:09:58.000000', NULL, 1),
(7531243, 1204337, 68504, '<td valign="top">a fine composition, dynamics all around.</td>', 'a fine composition, dynamics all around.', '2017-08-28 00:11:29.000000', NULL, 1),
